mapper.select:
select  from takeout_order o
left join takeout_merchant m on m.merchant_id = o.merchant_id
left join sys_user u on u.user_id = o.user_id

    and o.order_id = #{orderId}
    and o.order_no = #{orderNo}
    and o.request_no = #{requestNo}
    and o.user_id = #{userId}
    and o.merchant_id = #{merchantId}
    and m.merchant_name like concat('%', #{merchantName}, '%')
    and o.status = #{status}

order by o.create_time desc, o.order_id desc

mapper.update:
update takeout_order set status = #{toStatus},
    update_by = #{updateBy}, update_time = sysdate(), version = version + 1
where order_id = #{orderId} and status = #{fromStatus} and version = #{version}
